    sync_own_server: "Sync to your own server",
    sync_hosted_promise: "Your data is encrypted in this browser before it is uploaded, with a key derived from your password, so the server holds something it cannot read. That includes whoever runs it: they can see that your account exists and how large it is, and nothing else. It also means nobody can reset your password for you. Lose it and the copy on the server is lost with it, which is why you were asked to keep your own backup.",
    sync_promise: "This is the one part of the app that talks to a network. Your data is encrypted in this browser before it is uploaded, with a key derived from your password, so the server holds something it cannot read. Lose the password and the copy on the server is lost with it. Everything still works offline, the server is a copy and not the store. New accounts on a server are made by invitation from whoever set it up.",
    sync_insecure_origin: "Your browser only allows encryption on a secure origin, which means https, or localhost on the machine running the app. This page is neither, so the key cannot be derived and sync is switched off. Reach the app over https, or open it on the machine it runs on.",
    sync_expired_explain: "Nothing is wrong with your data, on this device or on the server. A session lasts thirty days, and every session on a server ends at once if its signing secret is changed. Type your password below to sign in again. The address, the username and the key on this device all stay as they are.",
