    pct_no_date_title: "No date can be given",
    pct_no_date_body: "No half-life is established in humans for {names}, so there is no honest clearance date. The real answer is later than the other compounds here suggest, by an unknown amount. Other tools will print a number anyway. This one will not.",
    pct_androgen_cleared: "Androgen has cleared",
