    pct_five_half_lives: "Taken as five half-lives from the last dose, which leaves about {percent}% behind. That is the usual pharmacological convention for cleared, not a physiological threshold. Starting earlier means a SERM spends the protocol competing with androgen that is still arriving.",
    pct_published: "Published protocols",
    pct_ends_around: "Started at the earliest date above, this ends around {ends}. Retest no sooner than {retest}: a SERM raises testosterone while it is still present, so bloods taken during it measure the drug, not the recovery.",
    pct_source: "Source",
    pct_footer: "None of these is an approved treatment for suppression caused by anabolic steroids, and none of it is advice to run one. What the app can tell you is when the androgen will be gone. Whether to take anything at that point is a question for a doctor who can test you.",
