    about_subtitle: "What it is, what happens to your data, and where the numbers come from.",
    about_what_it_is_2: "The parts that are easy to get wrong are the parts it takes seriously. Reconstitution arithmetic is exact and covered by tests. Blends are split into their components and each one modelled on its own half-life. A U-40 barrel is never quietly read as U-100. And the {compounds} compound library tags every dose figure with where it came from, so an approved label and a forum convention never look alike.",
    about_data_1: "By default there is no account, no server and no analytics. Everything you enter is stored in this browser, on this device, and never leaves it. Not to me, not to whoever is hosting it.",
    about_data_2: "One exception, and it is off unless you switch it on. In Settings you can point the app at a sync server you run yourself, so a second device can read the same data. Your data is encrypted in this browser before it is uploaded, with a key derived from your password, so that server holds something it cannot read either. Leave it alone and nothing is ever sent.",
    about_data_3: "That is a real privacy guarantee and a real risk at the same time. Nobody can read your data, and nobody can recover it for you either. Clearing your browsing data erases it. Export a copy from Settings and keep it somewhere else.",
    about_skipped_1: "Ticking **Record this as a skipped dose** writes an entry to your log and marks it as not taken. It is a record rather than the absence of one, and that is the entire point: the app can tell a dose you decided against from one nobody ever logged, and your adherence figure reports the two separately rather than lumping both under missed.",
    about_skipped_stops: "What it stops happening",
    about_skipped_vial: "No vial is drawn down. Change an existing dose from taken to skipped and the mass goes back into the vial it came from. Delete a skipped entry and nothing is returned, because nothing was taken.",
    about_skipped_curve: "No drug is modelled in your body, so the curve, the percentage of peak and the projection are all untouched.",
    about_skipped_ring: "It does not count towards today's ring or your streak, which count it apart from a dose taken.",
    about_skipped_left_out: "It is left out of the outcome comparisons, the injection site rotation, the dose marks on the weight chart, and the protocol the app infers from your history.",
    about_skipped_greyed: "The dose, units and vial fields grey out while the box is ticked, since none of them mean anything for a dose that did not happen.",
    about_skipped_shows: "Where it still shows up",
    about_skipped_where: "In the log with its own marker, in the Skipped figure for the last thirty days, as \"skipped\" in the printable report, and as skipped=yes in the CSV export.",
    about_tracks_compounds: "{n} compounds, with cited half-lives and dose ranges",
    about_tracks_protocols: "Protocols, titration ladders and adherence",
    about_tracks_reconstitution: "Reconstitution for U-100 and U-40 syringes",
    about_tracks_stock: "Vial stock, beyond-use dates and cost per dose",
    about_tracks_sites: "Injection site rotation",
    about_tracks_weight: "Weight, with Android Health read-in",
    about_tracks_markers: "{n} blood markers, charted against your doses",
    about_tracks_interactions: "Interaction checks across what you run together",
    about_whats_new: "What is new",
    about_hide: "Hide",
    about_show: "Show",
    about_contributors: "Contributors:",
    about_built_by: "Built by **Arun**, originally to track my own protocols properly, because every other option either wanted an account or got the arithmetic wrong. It is free, there is nothing to buy, and nothing about you is collected.",
    about_corrections: "Corrections to the library are welcome, particularly with a citation attached.",
    about_icon_credit: "App icon by {author} on {site}, used under the Flaticon licence.",
    about_not_body: "Not medical advice, not a prescription, and not a recommendation to use anything in it. Most compounds here are not approved medicines anywhere, and material sold for research use has no regulated identity, purity or sterility behind it. The app can check your arithmetic. It cannot check what is in your vial, and it is no substitute for a doctor who knows your history.",
    about_numbers_title: "Where the numbers come from",
    about_numbers_1: "Prescribing labels first, then published trials, then registries. Community practice is included where it is genuinely what people do, but it is always tagged as such.",
    about_numbers_2: "Where a half-life has never been measured in humans, as with trenbolone and several research peptides, the app says so and draws no curve rather than inventing one that looks authoritative. Every entry links its sources.",
    about_public_page: "The public page for this app",
    about_export_data: "Export your data",
