    account_sign_out_note: "Signing out sends anything unsent to the server first, then removes this browser's copy of your data and the key that reads it. That is on purpose: on a computer somebody else uses, leaving would otherwise leave your dose history behind for whoever opens it next. Nothing is lost, because the server keeps it and your password brings it back.",
