    // ── Calculator page ───────────────────────────────────────────────────────
    calc_title: "Rekonstitutionsrechner",
    calc_intro: "Rechne aus, wie viel Wasser zuzugeben ist und wie weit der Kolben zu ziehen ist. Die Spritze unten ist in den echten Proportionen des gewählten Zylinders gezeichnet, du kannst deine also an den Bildschirm halten.",
    calc_one_mark: "1 Strich = {ml} mL",
    calc_barrel_reads: "Zylinder von 0 bis {max}",
    calc_marks_every: "Striche alle {step}",
    calc_barrel_warning: "Ein U-40 Zylinder von 0 bis 40 und ein U-100 Zylinder von 0 bis 100 sehen ähnlich aus, aber ein Strich ist **0,025 mL** auf U-40 gegenüber **0,01 mL** auf U-100. Einen U-40 Zylinder wie einen U-100 zu lesen liefert die **2,5-fache** Dosis. Eine 0,4 mL U-100 Spritze gibt es nicht, eine \u201e40 Einheiten Spritze\u201c ist also höchstwahrscheinlich der 1 mL Veterinärzylinder U-40.",
    calc_peptide_optional: "Peptid (optional)",
    calc_peptide_hint: "Trägt eine übliche Ampullengröße und Dosis ein.",
    calc_choose_prefill: "Zum Vorausfüllen wählen\u2026",
    calc_water_hint: "Bakteriostatisches Wasser für eine Mehrdosenampulle.",
    calc_dose_you_want: "Gewünschte Dosis",
    calc_dashed_line: "Die gestrichelte Linie markiert den genauen Wert {units}, die Füllung zeigt den Strich, den du tatsächlich treffen kannst.",
