    calc_scale_marks: "{scale} Striche",
    calc_on_the_scale: "Auf der Skala {range}.",
    calc_mcg_per_mark: "{mcg} mcg pro gedrucktem Strich.",
    calc_doses_per_vial: "Dosen pro Ampulle",
    calc_at_each: "Zu je {dose}.",
    calc_same_volume_reads: "Dieselben {ml} lesen sich als",
    calc_marks_on_barrel: "Striche auf einem {scale} Zylinder.",
    calc_enter_to_see: "Gib Ampullenstärke, Wassermenge und Dosis ein, um den Zug zu sehen.",
    calc_cleaner_desc: "Gleiche Ampulle, gleiche Dosis, andere Wassermenge. Ein Zug, der genau auf einem gedruckten Strich landet, lässt sich jedes Mal genau wiederholen.",
    calc_lands_on_mark: "Landet auf einem Strich",
    calc_current: "aktuell",
    calc_displacement_note: "Das lyophilisierte Pulver selbst verdrängt etwa 0,7 Mikroliter pro Milligramm, eine 10 mg Ampulle verschiebt eine 2 mL Rekonstitution also um rund 0,35%, deutlich unter dem feinsten Strich auf jedem Zylinder. Es wird hier ignoriert, wie auch in der klinischen Praxis.",
    calc_disclaimer: "Die Rechnung hier ist exakt und getestet. Was sie nicht prüfen kann, ist, ob die Ampulle enthält, was das Etikett sagt, unreguliertes Material hat keine geprüfte Identität, Reinheit oder Sterilität, und richtige Mathematik an einem ungeprüften Produkt macht es nicht sicher. Nichts in dieser App ist ein medizinischer Rat.",
    calc_body_exceeds_barrel: "Nimm eine größere Spritze, teile die Dosis auf zwei Injektionen auf, oder rekonstituiere mit weniger Wasser für eine höhere Konzentration.",
    calc_body_below_graduation: "Das lässt sich nicht genau abmessen. Gib mehr Wasser dazu, oder nimm einen Zylinder mit feineren Strichen.",
    calc_body_off_graduation: "Du musst dich auf den nächsten Strich einigen. Die gelieferte Dosis unten berücksichtigt das.",
