    settings_data_note: "Alles lebt in diesem Browser auf diesem Gerät. Solange du unten keine Synchronisation einrichtest, gibt es kein Konto und keinen Server, es wird also nichts hochgeladen und nichts für dich gesichert. Die Browserdaten zu löschen löscht auch das, exportiere regelmäßig, wenn du es behalten willst. Die JSON-Datei stellt alles wieder her, die CSV ist nur die Dosishistorie, für eine Tabelle oder für den Arzt.",
