    settings_what_it_is: "Was diese App ist, und was nicht",
    settings_about_1: "Das ist ein persönliches Aufzeichnungswerkzeug. Es ist kein medizinischer Rat, kein Rezept und keine Empfehlung, irgendeine Verbindung darin zu verwenden.",
    settings_about_2: "Die Rekonstitutionsrechnung ist exakt und durch Tests abgedeckt. Was sie nicht prüfen kann, ist, ob eine Ampulle enthält, was ihr Etikett behauptet. Die meisten Verbindungen in der Bibliothek sind nirgends zugelassene Arzneimittel, und Material, das für Forschungszwecke verkauft wird, hat keine regulierte Identität, Reinheit, Sterilität oder Endotoxinnorm hinter sich.",
    settings_about_3: "Dosisangaben sind mit ihrer Herkunft gekennzeichnet. Ein zugelassenes Etikett und eine Gepflogenheit der Community werden beide gezeigt, sind aber nicht dieselbe Art von Information, und die App stellt sie nie so dar.",
    settings_profiles_note: "Jedes Profil führt eigene Protokolle, Dosen und Bestände. Nichts wird zwischen ihnen geteilt, und eine Dosis kann immer nur aus dem Bestand des Profils gehen, das sie eingetragen hat.",
