    settings_restored_from: "Aus {name} wiederhergestellt: {doses}, {protocols}, {vials}.",
    settings_backup_unreadable: "Diese Sicherung konnte nicht als JSON gelesen werden.",
    settings_health_desc: "Liest das Gewicht aus Android Health, damit ein Wert von deiner Waage hier auftaucht, und füllt das Gewichtsfeld mit dem neuesten vor. Es ist **eine Einbahnstraße**: nichts, was diese App hält, wird je zurückgeschrieben, und sie fragt nur nach Lesezugriff, hier kann also nichts ändern, was deine Waage oder Health Connect aufgezeichnet hat. Ein Wert, den du kurz vor der Synchronisation deiner Waage getippt hast, wird ihm zugeordnet statt doppelt geführt.",
