    sync_setup_token_placeholder: "eine Hex-Zeichenkette aus dem Serverlog",
    sync_own_server: "Mit deinem eigenen Server synchronisieren",
    sync_hosted_promise: "Deine Daten werden in diesem Browser verschlüsselt, bevor sie hochgeladen werden, mit einem Schlüssel aus deinem Passwort, der Server hält also etwas, das er nicht lesen kann. Das gilt auch für den Betreiber: er sieht, dass dein Konto existiert und wie groß es ist, sonst nichts. Es heißt auch, dass niemand dein Passwort für dich zurücksetzen kann. Verlierst du es, ist die Kopie auf dem Server mit verloren, deshalb wurdest du gebeten, eine eigene Sicherung zu behalten.",
    sync_promise: "Das ist der einzige Teil der App, der mit einem Netzwerk spricht. Deine Daten werden in diesem Browser verschlüsselt, bevor sie hochgeladen werden, mit einem Schlüssel aus deinem Passwort, der Server hält also etwas, das er nicht lesen kann. Verlierst du das Passwort, ist die Kopie auf dem Server mit verloren. Alles funktioniert weiter offline, der Server ist eine Kopie und nicht der Speicher. Neue Konten auf einem Server entstehen per Einladung von dem, der ihn eingerichtet hat.",
    sync_insecure_origin: "Dein Browser erlaubt Verschlüsselung nur auf einem sicheren Ursprung, also https oder localhost auf dem Rechner, der die App ausführt. Diese Seite ist weder noch, der Schlüssel lässt sich also nicht ableiten und die Synchronisation ist aus. Erreiche die App über https, oder öffne sie auf dem Rechner, auf dem sie läuft.",
    sync_expired_explain: "Mit deinen Daten ist nichts falsch, weder auf diesem Gerät noch auf dem Server. Eine Sitzung hält dreißig Tage, und alle Sitzungen auf einem Server enden auf einmal, wenn sein Signaturgeheimnis geändert wird. Tippe unten dein Passwort, um dich erneut anzumelden. Adresse, Benutzername und der Schlüssel auf diesem Gerät bleiben, wie sie sind.",
    sync_key_not_kept: "Dieser Browser behält den Schlüssel nicht zwischen Besuchen, was private Fenster besonders konsequent verweigern. Die Synchronisation läuft, solange dieser Tab offen bleibt.",
    sync_conflict_explain: "Dieses Gerät und der Server wurden beide geändert, seit sie zuletzt übereinstimmten. Eines zu behalten heißt das andere zu verwerfen, es wurde also nichts gesendet oder geholt, bis du sagst welches.",
    sync_server_label: "Server:",
