    unlock_slow: "Es dauert einen Moment. Ein Passwort in einen Schlüssel zu verwandeln ist absichtlich langsam, und genau das macht es lohnend, nur einmal zu raten.",
    backup_gate_title: "Eine Sache, bevor du anfängst",
    backup_gate_encrypted: "Dein Passwort ist der Schlüssel zu deinen Daten. Alles wird in diesem Browser verschlüsselt, bevor es zum Server geht, also liegt dort etwas, das der Server nicht lesen kann. Das gilt auch für die Person, die ihn betreibt: sie sieht, dass dein Konto existiert und wie groß es ist, sonst nichts.",
    backup_gate_no_reset: "Niemand kann dein Passwort zurücksetzen. Nicht die Person, die den Server betreibt, niemand. Wenn du es verlierst, bleibt die Kopie dort oben für immer verschlossen.",
    backup_gate_keep_copy: "Behalte also deine eigene Kopie. Das speichert eine Datei mit allem darin, die du später über die Einstellungen zurückholen kannst. Es ist dieselbe Schaltfläche wie oben in der Kopfzeile, du kannst das also jederzeit wieder tun, und es lohnt sich.",
