    admin_title: "Dieser Server",
    admin_intro: "Dir gehört dieser Server, du siehst also, wer ein Konto darauf hat, und kannst weitere Leute einladen. Was sie erfasst haben, siehst du nicht. Der Server hält ihre Daten mit ihrem eigenen Passwort versiegelt und hat keinen Schlüssel dazu, und das heißt auch, dass weder du noch sonst jemand ein Passwort zurücksetzen kann.",
