    admin_clear: "Aufräumen",
    import_intro: "Liest einen Export im Format CSV, TSV, JSON oder .xlsx aus einem anderen Tracker und führt die Dosen und Gewichte in dieses Profil ein. Ein Laborbericht als PDF wird hier ebenfalls gelesen, direkt auf diesem Gerät: nichts wird irgendwohin hochgeladen. Shotsy wird am Namen erkannt; alles andere wird aus den Spaltenüberschriften gelesen, eine Tabelle mit Datum, Mittel und Dosis funktioniert also. Nichts wird geschrieben, bevor du gesehen hast, was gefunden wurde, und ein erneuter Import derselben Datei fügt später nur Neues hinzu.",
