    reminders_intro: "Eine Erinnerung zur Stunde, in der eine Dosis fällig ist. Vom Telefon selbst geplant, also funktioniert es bei geschlossener App und ohne Verbindung, und **es wird nichts irgendwohin gesendet**. Eine früh eingetragene Dosis storniert ihre eigene Erinnerung, damit das Telefon nicht nach etwas fragt, das schon im Bein steckt.",
