    reminders_export: "Dosen in den Kalender exportieren",
    reminders_calendar_note: "Jede Dosis wird ein Termin mit eigenem Alarm, dein Kalender übernimmt also das Erinnern. Importiere ihn in einen **eigenen Kalender** statt in deinen Hauptkalender: eine Planänderung heißt erneut exportieren, und ein separater Kalender lässt sich in einem Zug leeren, statt Termine einzeln zu suchen.",
    reminders_named_warning: "Du hast dich entschieden, die Substanz zu benennen. Ein Kalender, der mit Google oder Apple synchronisiert, trägt diesen Namen dorthin, was sonst nichts in dieser App tut. Stell die Einstellung oben wieder auf diskret, falls das eine Rolle spielt.",
    reminders_nothing_to_export: "Nichts zu exportieren. In diesem Zeitraum stehen keine Dosen an.",
