    reminders_exported: "{doses} exportiert. Importiere {name} in deinen Kalender.",
    pct_cleared_badge: "eliminiert",
    pct_not_computable_badge: "nicht berechenbar",
    pct_still_clearing_badge: "noch am Abklingen",
    pct_recovery_timing: "Zeitplan der Erholung",
    pct_last_dose: "letzte Dosis {date}",
    pct_cleared_line: "Eliminiert.",
    pct_left_line: "Noch etwa {percent}% der letzten Dosis übrig. Eliminiert um den {date} herum, in {duration}.",
    pct_no_date_title: "Ein Datum kann nicht angegeben werden",
    pct_no_date_body: "Für {names} ist beim Menschen keine Halbwertszeit belegt, es gibt also kein ehrliches Datum der Elimination. Die echte Antwort liegt später, als die anderen Substanzen hier vermuten lassen, um einen unbekannten Betrag. Andere Werkzeuge drucken trotzdem eine Zahl. Dieses nicht.",
    pct_androgen_cleared: "Androgen ist eliminiert",
    pct_earliest_start: "Frühester sinnvoller Start: {date}",
    pct_five_half_lives: "Gerechnet als fünf Halbwertszeiten ab der letzten Dosis, womit noch etwa {percent}% übrig bleiben. Das ist die übliche pharmakologische Konvention für eliminiert, keine physiologische Schwelle. Früher zu starten heißt, dass ein SERM das ganze Protokoll gegen Androgen anläuft, das noch ankommt.",
    pct_published: "Publizierte Protokolle",
    pct_ends_around: "Ab dem frühesten Datum oben gestartet, endet das um den {ends} herum. Nicht früher als {retest} nachtesten: ein SERM hebt das Testosteron, solange es noch da ist, Blut während der Einnahme misst also das Medikament und nicht die Erholung.",
    pct_source: "Quelle",
    pct_footer: "Nichts davon ist eine zugelassene Behandlung der durch anabole Steroide verursachten Suppression, und nichts davon ist ein Rat, so etwas zu machen. Was die App dir sagen kann, ist, wann das Androgen weg sein wird. Ob man dann etwas nimmt, ist eine Frage für eine Ärztin, die dich testen kann.",
    count_things_one: "{n} Sache",
    count_things_other: "{n} Dinge",
    stack_all_clear: "Keine Wechselwirkungen über deine {protocols} aktiven Protokolle hinweg, keine gemeinsamen Rezeptorziele und keine Substanz, die zweimal ankommt.",
    stack_compact: "{things}, die du zum gemeinsamen Laufen wissen solltest.",
    stack_see_plan: "{title}. Details unter Plan.",
    stack_footnote: "Das sind Beobachtungen auf Mechanismusebene aus der Bibliothek, keine klinische Beratung, und das Fehlen einer Warnung ist keine Unbedenklichkeit, die meisten dieser Substanzen wurden in Kombination überhaupt nie untersucht.",
    labs_card_all_results: "Alle Ergebnisse",
    labs_card_add_results: "Ergebnisse eintragen",
    labs_card_title: "Blutwerte",
    labs_card_worth_checking: "Für das, was du läufst, einen Blick wert:",
