    hwp_empty_action: "Ein Protokoll anlegen",
    hwp_empty_body: "Leg ein Protokoll an und diese Seite wird dein Überblick: was ansteht, was noch zirkuliert und wie viel du auf Lager hast. Du trackst schon woanders? Importiere eine CSV in den Einstellungen und deine Historie kommt mit.",
    hwp_title: "Deine Historie ist da, der Plan nicht",
    hwp_body: "{doses} erfasst und kein Protokoll angelegt, es steht also nichts an und die Wirkstoffkurve hat nichts, was sie fortschreiben könnte. So sieht das aus, dem deine Historie gefolgt zu sein scheint, prüf es und übernimm es, oder leg selbst eines an.",
