    site_legend_used_recently: "kürzlich genutzt",
    site_legend_rested: "ausgeruht",
    site_legend_suggested: "als Nächstes vorgeschlagen",
    site_legend_off_plan: "nicht im Plan",
    about_subtitle: "Was es ist, was mit deinen Daten geschieht und woher die Zahlen kommen.",
    about_what_it_is_2: "Die Teile, die leicht falsch werden, sind die, die es ernst nimmt. Die Rekonstitutionsrechnung ist exakt und durch Tests abgedeckt. Mischungen werden in ihre Bestandteile zerlegt und jeder auf seiner eigenen Halbwertszeit modelliert. Ein U-40-Zylinder wird nie stillschweigend als U-100 gelesen. Und die Bibliothek mit {compounds} Substanzen kennzeichnet jede Dosisangabe mit ihrer Herkunft, damit eine zugelassene Fachinformation und eine Forumsgepflogenheit nie gleich aussehen.",
    about_data_1: "Standardmäßig gibt es kein Konto, keinen Server und keine Analyse. Alles, was du einträgst, liegt in diesem Browser, auf diesem Gerät, und verlässt es nie. Nicht zu mir, nicht zu dem, der es hostet.",
    about_data_2: "Eine Ausnahme, und sie ist aus, solange du sie nicht einschaltest. In den Einstellungen kannst du die App auf einen selbst betriebenen Sync-Server richten, damit ein zweites Gerät dieselben Daten lesen kann. Deine Daten werden in diesem Browser verschlüsselt, bevor sie hochgeladen werden, mit einem aus deinem Passwort abgeleiteten Schlüssel, dieser Server hält also ebenfalls etwas, das er nicht lesen kann. Lass es aus und es wird nie etwas gesendet.",
    about_data_3: "Das ist zugleich eine echte Zusicherung und ein echtes Risiko. Niemand kann deine Daten lesen, und niemand kann sie dir wiederherstellen. Das Löschen deiner Browserdaten löscht sie. Exportiere in den Einstellungen eine Kopie und bewahre sie woanders auf.",
    about_skipped_1: "Ein Haken bei **Als ausgelassene Dosis erfassen** schreibt einen Eintrag in dein Log und markiert ihn als nicht genommen. Das ist ein Eintrag statt keines, und genau darum geht es: die App kann eine bewusst ausgelassene Dosis von einer unterscheiden, die nie jemand erfasst hat, und deine Einhaltung weist beide getrennt aus, statt alles unter verpasst zu bündeln.",
    about_skipped_stops: "Was dadurch nicht passiert",
    about_skipped_vial: "Keine Ampulle wird abgezogen. Änderst du eine bestehende Dosis von genommen auf ausgelassen, geht die Menge in die Ampulle zurück, aus der sie kam. Löschst du einen ausgelassenen Eintrag, wird nichts zurückgegeben, weil nichts entnommen wurde.",
    about_skipped_curve: "Es wird kein Wirkstoff im Körper modelliert, die Kurve, der Prozentsatz vom Maximum und die Projektion bleiben also unberührt.",
    about_skipped_ring: "Es zählt nicht für den heutigen Ring oder deine Serie, die es getrennt von einer genommenen Dosis zählen.",
    about_skipped_left_out: "Es bleibt außen vor bei den Ergebnisvergleichen, der Rotation der Injektionsstellen, den Dosismarken auf der Gewichtskurve und dem Protokoll, das die App aus deiner Historie ableitet.",
    about_skipped_greyed: "Die Felder für Dosis, Einheiten und Ampulle werden ausgegraut, solange der Haken gesetzt ist, denn für eine Dosis, die nicht stattfand, bedeutet keines davon etwas.",
    about_skipped_shows: "Wo es trotzdem auftaucht",
    about_skipped_where: "Im Log mit eigener Markierung, in der Zahl der ausgelassenen Dosen der letzten dreißig Tage, als \"skipped\" im druckbaren Bericht und als skipped=yes im CSV-Export.",
    about_tracks_compounds: "{n} Substanzen, mit belegten Halbwertszeiten und Dosisbereichen",
    about_tracks_protocols: "Protokolle, Titrationsleitern und Einhaltung",
    about_tracks_reconstitution: "Rekonstitution für U-100- und U-40-Spritzen",
    about_tracks_stock: "Ampullenbestand, Aufbrauchfristen und Kosten pro Dosis",
    about_tracks_sites: "Rotation der Injektionsstellen",
    about_tracks_weight: "Gewicht, mit Android-Health-Einlesen",
    about_tracks_markers: "{n} Blutmarker, aufgetragen gegen deine Dosen",
    about_tracks_interactions: "Wechselwirkungsprüfung über das, was du zusammen läufst",
    about_whats_new: "Was neu ist",
    about_hide: "Ausblenden",
    about_show: "Zeigen",
    about_contributors: "Mitwirkende:",
    about_built_by: "Gebaut von **Arun**, ursprünglich um meine eigenen Protokolle ordentlich zu verfolgen, weil jede andere Möglichkeit entweder ein Konto wollte oder sich verrechnete. Es ist kostenlos, es gibt nichts zu kaufen, und nichts über dich wird erhoben.",
    about_corrections: "Korrekturen an der Bibliothek sind willkommen, besonders mit einer Quelle dabei.",
    about_icon_credit: "App-Icon von {author} auf {site}, verwendet unter der Flaticon-Lizenz.",
    about_not_body: "Keine medizinische Beratung, kein Rezept und keine Empfehlung, irgendetwas davon zu verwenden. Die meisten Substanzen hier sind nirgends zugelassene Arzneimittel, und Material, das für Forschungszwecke verkauft wird, hat keine regulierte Identität, Reinheit oder Sterilität hinter sich. Die App kann deine Rechnung prüfen. Was in deiner Ampulle ist, kann sie nicht prüfen, und sie ersetzt keine Ärztin, die deine Vorgeschichte kennt.",
    about_numbers_title: "Woher die Zahlen kommen",
    about_numbers_1: "Zuerst Fachinformationen, dann publizierte Studien, dann Register. Gängige Praxis ist enthalten, wo sie wirklich das ist, was Leute tun, aber sie ist immer als solche gekennzeichnet.",
    about_numbers_2: "Wo eine Halbwertszeit beim Menschen nie gemessen wurde, wie bei Trenbolon und mehreren Forschungspeptiden, sagt die App das und zeichnet keine Kurve, statt eine zu erfinden, die maßgeblich aussieht. Jeder Eintrag verlinkt seine Quellen.",
    about_public_page: "Die öffentliche Seite dieser App",
    about_export_data: "Deine Daten exportieren",
    dismiss: "Verwerfen",
    later: "Später",
    language: "Sprache",
