    account_title: "Dein Konto",
    account_sign_out_note: "Beim Abmelden geht zuerst alles Ungesendete an den Server, dann werden die Kopie deiner Daten in diesem Browser und der Schlüssel, der sie liest, entfernt. Das ist Absicht: auf einem Computer, den auch andere benutzen, bliebe sonst deine Dosishistorie für den zurück, der ihn als Nächstes öffnet. Verloren geht nichts, denn der Server behält sie und dein Passwort holt sie zurück.",
