    now_curve_note: "Prikazane ravni so ocenjena masa v obtoku in ne koncentracija v plazmi. Model uporablja objavljene razpolovne dobe in enoprostorno Batemanovo enačbo, prilagojeno dozam, ki si jih zabeležil. Biološka uporabnost in volumen porazdelitve za večino teh učinkovin nista objavljena, zato je številka farmakokinetična ocena in ne izmerjena vrednost v krvi. Trikotniki označujejo zabeležene doze. Kjer odčitek imenuje vialko, se njena jakost bere taka, kakršna je danes.",
