    sync_hosted_promise: "Tvoji podatki se šifrirajo v tem brskalniku, preden se naložijo, s ključem iz tvojega gesla, zato strežnik hrani nekaj, česar ne more prebrati. To velja tudi za tistega, ki ga poganja: vidi lahko, da tvoj račun obstaja in kako velik je, drugega nič. Pomeni tudi, da ti gesla ne more nihče ponastaviti. Če ga izgubiš, je kopija na strežniku izgubljena z njim, in prav zato si bil naprošen, da hraniš svojo varnostno kopijo.",
    sync_promise: "To je edini del aplikacije, ki govori z omrežjem. Tvoji podatki se šifrirajo v tem brskalniku, preden se naložijo, s ključem iz tvojega gesla, zato strežnik hrani nekaj, česar ne more prebrati. Če izgubiš geslo, je kopija na strežniku izgubljena z njim. Vse deluje naprej brez povezave, strežnik je kopija in ne shramba. Novi računi na strežniku nastanejo s povabilom tistega, ki ga je postavil.",
    sync_insecure_origin: "Tvoj brskalnik dovoli šifriranje samo na varnem izvoru, kar pomeni https ali localhost na računalniku, ki poganja aplikacijo. Ta stran ni ne eno ne drugo, zato ključa ni mogoče izpeljati in sinhronizacija je izklopljena. Do aplikacije pridi prek https ali jo odpri na računalniku, kjer teče.",
    sync_expired_explain: "S tvojimi podatki ni nič narobe, ne na tej napravi ne na strežniku. Seja traja trideset dni, vse seje na strežniku pa se končajo naenkrat, če se spremeni njegova podpisna skrivnost. Spodaj vtipkaj geslo za ponovno prijavo. Naslov, uporabniško ime in ključ na tej napravi ostanejo taki, kot so.",
    sync_key_not_kept: "Ta brskalnik ključa med obiski ne obdrži, česar zasebna okna še posebej ne počnejo. Sinhronizacija deluje, dokler je ta zavihek odprt.",
    sync_conflict_explain: "Ta naprava in strežnik sta bila oba spremenjena, odkar sta se nazadnje ujemala. Obdržati enega pomeni zavreči drugega, zato ni bilo nič poslano ali prevzeto, dokler ne poveš, katerega.",
    sync_server_label: "Strežnik:",
