    notice_keep_device: "Obdrži kopijo te naprave",
    notice_take_server: "Vzemi kopijo s strežnika",
    notice_conflict: "Ta naprava in strežnik sta se oba spremenila, odkar sta se nazadnje ujemala. Nič se ne pošilja in nič ne prevzema, dokler ne poveš, katero kopijo obdržati, zato vse, kar tukaj narediš, zaenkrat ostaja na tej napravi.",
    notice_expired: "Tvoja seja je potekla, zato se nič ne pošilja. Vse, kar tukaj narediš, je varno na tej napravi. Prijavi se znova v Nastavitvah pod Sync in nadoknadilo bo.",
