    backup_gate_title: "Ena stvar, preden začneš",
    backup_gate_encrypted: "Tvoje geslo je ključ do tvojih podatkov. Vse se šifrira v tem brskalniku, še preden odide na strežnik, tako da strežnik hrani nekaj, česar ne more prebrati. To velja tudi za tistega, ki ga upravlja: vidi lahko, da tvoj račun obstaja in kako velik je, drugega pa nič.",
    backup_gate_no_reset: "Nihče ne more ponastaviti tvojega gesla. Ne tisti, ki upravlja strežnik, nihče. Če ga izgubiš, kopija tam gori ostane za vedno zaklenjena.",
    backup_gate_keep_copy: "Zato obdrži svojo kopijo. To shrani datoteko z vsem, kar imaš, in jo lahko pozneje vrneš iz Nastavitev. To je isti gumb, ki stoji v glavi strani, torej lahko to storiš znova, kadarkoli želiš, in se splača.",
    backup_gate_save: "Shrani varnostno kopijo in nadaljuj",
    backup_gate_small: "Nov račun ima v sebi še skoraj nič, zato bo datoteka majhna. To je pričakovano. Bistvo je, da jo imaš in veš, kam je šla.",
