    import_intro: "Prebere izvoz v obliki CSV, TSV, JSON ali .xlsx iz drugega sledilnika in doze ter teže združi v ta profil. Tudi izvid v obliki PDF se prebere tukaj, kar na tej napravi: nikamor se nič ne naloži. Shotsy prepozna po imenu, vse drugo prebere iz glav stolpcev, tako da preglednica z datumom, snovjo in dozo deluje. Nič se ne zapiše, dokler ne vidiš, kaj je našel, in ponoven uvoz iste datoteke pozneje doda samo tisto, kar je novo.",
