    site_legend_off_plan: "zunaj načrta",
    about_subtitle: "Kaj to je, kaj se zgodi s tvojimi podatki in od kod prihajajo številke.",
    about_what_it_is_2: "Deli, ki jih je lahko zgrešiti, so tisti, ki jih jemlje resno. Računanje rekonstitucije je natančno in pokrito s testi. Mešanice se razdelijo na sestavine in vsaka se modelira po svojem razpolovnem času. Cilinder U-40 se nikoli tiho ne bere kot U-100. Knjižnica s {compounds} snovmi pa vsako številko doze označi z izvorom, tako da odobreno navodilo in forumska navada nikoli nista videti enaka.",
    about_data_1: "Privzeto ni računa, ni strežnika in ni analitike. Vse, kar vneseš, je shranjeno v tem brskalniku, na tej napravi, in tega nikoli ne zapusti. Ne k meni, ne k tistemu, ki gostuje aplikacijo.",
    about_data_2: "Ena izjema, in ta je izklopljena, dokler je ne vklopiš. V Nastavitvah lahko aplikacijo usmeriš na strežnik za sinhronizacijo, ki ga poganjaš sam, da druga naprava bere iste podatke. Tvoji podatki se šifrirajo v tem brskalniku, preden se naložijo, s ključem, izpeljanim iz tvojega gesla, tako da tudi ta strežnik hrani nekaj, česar ne more prebrati. Pusti to pri miru in ne bo poslano nikoli nič.",
    about_data_3: "To je hkrati resnično jamstvo zasebnosti in resnično tveganje. Tvojih podatkov ne more prebrati nihče, in tudi obnoviti ti jih ne more nihče. Če počistiš podatke brskanja, jih izbrišeš. Izvozi kopijo iz Nastavitev in jo hrani kje drugje.",
    about_skipped_1: "Kljukica pri **Zabeleži to kot preskočeno dozo** zapiše vnos v tvoj dnevnik in ga označi kot nevzet. To je zapis in ne odsotnost zapisa, in prav v tem je bistvo: aplikacija loči dozo, ki si se ji namenoma odpovedal, od tiste, ki je ni nihče nikoli zabeležil, tvoja doslednost pa obe poroča ločeno, namesto da bi ju obe stlačila pod zamujeno.",
    about_skipped_stops: "Kaj s tem ne nastane",
    about_skipped_vial: "Nobena vialka se ne odšteje. Če obstoječo dozo spremeniš iz vzete v preskočeno, gre masa nazaj v vialko, iz katere je prišla. Če izbrišeš preskočen vnos, se ne vrne nič, ker ni bilo nič vzeto.",
    about_skipped_curve: "V telesu se ne modelira nobena učinkovina, zato krivulja, odstotek vrha in projekcija ostanejo nedotaknjeni.",
    about_skipped_ring: "Ne šteje k današnjemu obroču ali tvojemu nizu, ki ga štejeta ločeno od vzete doze.",
    about_skipped_left_out: "Izpuščeno je iz primerjav izidov, kroženja mest vboda, oznak doz na grafu teže in protokola, ki ga aplikacija sklepa iz tvoje zgodovine.",
    about_skipped_greyed: "Polja za dozo, enote in vialko posivijo, dokler je kljukica postavljena, saj za dozo, ki se ni zgodila, nobeno od njih ne pomeni nič.",
    about_skipped_shows: "Kje se vseeno pokaže",
    about_skipped_where: "V dnevniku s svojo oznako, v številki preskočenih za zadnjih trideset dni, kot \"skipped\" v poročilu za tiskanje in kot skipped=yes v izvozu CSV.",
    about_tracks_compounds: "{n} snovi, z navedenimi razpolovnimi časi in razponi doz",
    about_tracks_protocols: "Protokoli, titracijske lestvice in doslednost",
    about_tracks_reconstitution: "Rekonstitucija za brizge U-100 in U-40",
    about_tracks_stock: "Zaloga vialk, roki uporabe po odprtju in strošek na dozo",
    about_tracks_sites: "Kroženje mest vboda",
    about_tracks_weight: "Teža, z branjem iz Android Health",
    about_tracks_markers: "{n} krvnih označevalcev, izrisanih ob tvojih dozah",
    about_tracks_interactions: "Preverjanje interakcij med tem, kar jemlješ skupaj",
    about_whats_new: "Kaj je novega",
    about_hide: "Skrij",
    about_show: "Pokaži",
    about_contributors: "Sodelujoči:",
    about_built_by: "Zgradil **Arun**, sprva zato, da bi si spodobno sledil lastnim protokolom, ker je vsaka druga možnost hotela račun ali pa je narobe računala. Je brezplačno, ni česa kupiti in o tebi se ne zbira nič.",
    about_corrections: "Popravki knjižnice so dobrodošli, še posebej z navedbo vira.",
    about_icon_credit: "Ikona aplikacije: {author} na {site}, uporabljena pod licenco Flaticon.",
    about_not_body: "Ni zdravniški nasvet, ni recept in ni priporočilo za uporabo česarkoli od tega. Večina snovi tukaj nikjer ni odobreno zdravilo, snov, prodana za raziskovalno rabo, pa za sabo nima regulirane identitete, čistosti ali sterilnosti. Aplikacija lahko preveri tvoj račun. Kaj je v tvoji vialki, ne more preveriti, in ni nadomestilo za zdravnika, ki pozna tvojo zgodovino.",
    about_numbers_title: "Od kod prihajajo številke",
    about_numbers_1: "Najprej navodila za predpisovanje, nato objavljene raziskave, nato registri. Praksa skupnosti je vključena tam, kjer je res tisto, kar ljudje počnejo, a je vedno tako označena.",
    about_numbers_2: "Kjer razpolovni čas pri ljudeh ni bil nikoli izmerjen, kot pri trenbolonu in več raziskovalnih peptidih, aplikacija to pove in ne nariše krivulje, namesto da bi si izmislila takšno, ki je videti verodostojna. Vsak vnos ima povezave do svojih virov.",
    about_public_page: "Javna stran te aplikacije",
