    settings_one_row_compound: "Jeden wiersz na substancję i moc",
    settings_data_note: "Wszystko żyje w tej przeglądarce na tym urządzeniu. Dopóki poniżej nie ustawisz synchronizacji, nie ma konta ani serwera, więc nic nie jest wysyłane i nic nie jest za ciebie kopiowane. Wyczyszczenie danych przeglądarki to usunie, więc eksportuj regularnie, jeśli chcesz to zachować. Plik JSON przywraca wszystko, CSV to tylko historia dawek, do arkusza albo dla lekarza.",
