    settings_what_it_is: "Czym ta aplikacja jest, a czym nie",
    settings_about_1: "To osobiste narzędzie do prowadzenia zapisów. Nie jest poradą lekarską, receptą ani zachętą do stosowania jakiejkolwiek substancji w nim.",
    settings_about_2: "Arytmetyka rozpuszczania jest dokładna i pokryta testami. Nie może sprawdzić, czy fiolka zawiera to, co twierdzi etykieta. Większość substancji w bibliotece nigdzie nie jest zarejestrowanym lekiem, a materiał sprzedawany do badań nie ma za sobą żadnego regulowanego standardu tożsamości, czystości, sterylności ani endotoksyn.",
    settings_about_3: "Dane o dawkach są oznaczone źródłem. Zarejestrowane wskazanie i praktyka społeczności są oba pokazane, ale nie są tym samym rodzajem informacji i aplikacja nigdy nie przedstawia ich tak, jakby były.",
    settings_profiles_note: "Każdy profil prowadzi własne protokoły, dawki i zapas. Nic nie jest między nimi dzielone, a dawka zawsze może pobierać tylko z zapasu profilu, który ją zapisał.",
