    settings_weight_unset: "Dodaj wagę, aby zobaczyć dawki w mcg/kg.",
    settings_showing: "pokazywane",
    settings_switch_to: "Przełącz na",
    settings_backups_web: "Strona internetowa nie może sama pisać do folderu, więc to działa w aplikacji na Androida. W przeglądarce kopię trzeba zapisać ręcznie: przycisk **Backup** w nagłówku robi to z każdego ekranu, a **{export}** poniżej robi to samo.",
    settings_take_one: "Rób",
    settings_take_one_hint: "Co jakiś czas, przy starcie aplikacji.",
