    settings_copies: "kopii",
    settings_last_backup: "Ostatnia kopia",
    settings_no_backups: "Jeszcze brak kopii.",
    settings_restore: "Przywróć",
    settings_restore_confirm: "Przywrócenie zastępuje wszystko, co jest teraz w aplikacji, zawartością tego pliku. Wszystko zapisane od {date} zniknie. Nie ma cofnięcia, więc zrób najpierw kopię, jeśli nie masz pewności.",
    settings_keep_what_i_have: "Zachowaj to, co mam",
    settings_replace_all: "Zastąp wszystko tym",
    settings_restored_from: "Przywrócono z {name}: {doses}, {protocols}, {vials}.",
    settings_backup_unreadable: "Tej kopii nie udało się odczytać jako JSON.",
    settings_health_desc: "Czyta wagę z Android Health, żeby odczyt z twojej wagi pojawił się tutaj, i wypełnia pole wagi najnowszym. Działa **tylko w jedną stronę**: nic, co ta aplikacja przechowuje, nigdy nie jest zapisywane z powrotem, a prosi tylko o dostęp do odczytu, więc nic tutaj nie może zmienić tego, co zapisała twoja waga albo Health Connect. Odczyt wpisany tuż przed synchronizacją wagi jest z nią łączony, a nie dublowany.",
    settings_health_30_days: "Health Connect nie odda odczytów starszych niż mniej więcej 30 dni, więc pierwsza synchronizacja pobiera ostatni miesiąc, a nie całą twoją historię.",
