    settings_backups_desc: "Zapisuje pełną kopię do **Documents/Bench** na tym urządzeniu i zachowuje kilka najnowszych. Nic nie opuszcza telefonu. To druga kopia w folderze, do którego dotrzesz menedżerem plików, a nie synchronizacja w chmurze, więc przetrwa wyczyszczenie danych aplikacji, ale nie utratę urządzenia. Skopiuj czasem jedną gdzie indziej, jeśli to dla ciebie ważne.",
