    sync_setup_token_hint: "Wypisywany w logu serwera przy starcie, dopóki nie ma jeszcze konta. docker compose logs sync",
    sync_setup_token_placeholder: "ciąg szesnastkowy z logu serwera",
    sync_own_server: "Synchronizacja z własnym serwerem",
    sync_hosted_promise: "Twoje dane są szyfrowane w tej przeglądarce przed wysłaniem, kluczem wyprowadzonym z twojego hasła, więc serwer trzyma coś, czego nie może odczytać. Dotyczy to także tego, kto go prowadzi: widzi, że twoje konto istnieje i jak jest duże, i nic więcej. Znaczy to również, że nikt nie zresetuje ci hasła. Gdy je zgubisz, kopia na serwerze przepada razem z nim, i właśnie dlatego poproszono cię o własną kopię zapasową.",
    sync_promise: "To jedyna część aplikacji, która rozmawia z siecią. Twoje dane są szyfrowane w tej przeglądarce przed wysłaniem, kluczem wyprowadzonym z hasła, więc serwer trzyma coś, czego nie może odczytać. Gdy zgubisz hasło, kopia na serwerze przepada razem z nim. Wszystko dalej działa offline, serwer jest kopią, a nie magazynem. Nowe konta na serwerze powstają z zaproszenia od tego, kto go postawił.",
    sync_insecure_origin: "Twoja przeglądarka pozwala na szyfrowanie tylko w bezpiecznym źródle, czyli https albo localhost na maszynie, która uruchamia aplikację. Ta strona nie jest ani jednym, ani drugim, więc klucza nie da się wyprowadzić i synchronizacja jest wyłączona. Wejdź do aplikacji przez https albo otwórz ją na maszynie, na której działa.",
    sync_expired_explain: "Z twoimi danymi wszystko w porządku, i na tym urządzeniu, i na serwerze. Sesja trwa trzydzieści dni, a wszystkie sesje na serwerze kończą się naraz, jeśli zmieni się jego sekret podpisujący. Wpisz poniżej hasło, żeby zalogować się ponownie. Adres, nazwa użytkownika i klucz na tym urządzeniu zostają bez zmian.",
    sync_key_not_kept: "Ta przeglądarka nie zachowa klucza między wizytami, czego okna prywatne w szczególności odmawiają. Synchronizacja działa tak długo, jak ta karta jest otwarta.",
    sync_conflict_explain: "To urządzenie i serwer zmieniły się oba, odkąd ostatnio się zgadzały. Zachowanie jednego oznacza odrzucenie drugiego, więc nic nie zostało wysłane ani pobrane, dopóki nie powiesz którego.",
