    about_subtitle: "Czym to jest, co dzieje się z twoimi danymi i skąd biorą się liczby.",
    about_what_it_is_2: "Te części, które łatwo zepsuć, są tymi, które traktuje poważnie. Arytmetyka rozpuszczania jest dokładna i pokryta testami. Mieszanki są rozbijane na składniki i każdy modelowany na własnym okresie półtrwania. Cylinder U-40 nigdy nie jest po cichu czytany jako U-100. A biblioteka {compounds} substancji oznacza każdą liczbę dawki źródłem, z którego pochodzi, żeby zatwierdzona charakterystyka i zwyczaj z forum nigdy nie wyglądały tak samo.",
    about_data_1: "Domyślnie nie ma konta, serwera ani analityki. Wszystko, co wpisujesz, jest przechowywane w tej przeglądarce, na tym urządzeniu, i nigdy jej nie opuszcza. Ani do mnie, ani do tego, kto to hostuje.",
    about_data_2: "Jeden wyjątek, i jest wyłączony, dopóki go nie włączysz. W Ustawieniach możesz wskazać aplikacji serwer synchronizacji, który prowadzisz sam, żeby drugie urządzenie czytało te same dane. Twoje dane są szyfrowane w tej przeglądarce przed wysłaniem, kluczem wyprowadzonym z twojego hasła, więc ten serwer też trzyma coś, czego nie potrafi odczytać. Zostaw to w spokoju, a nic nigdy nie zostanie wysłane.",
    about_data_3: "To jednocześnie prawdziwa gwarancja prywatności i prawdziwe ryzyko. Nikt nie odczyta twoich danych, i nikt ci ich też nie odzyska. Wyczyszczenie danych przeglądania je kasuje. Wyeksportuj kopię z Ustawień i trzymaj ją gdzie indziej.",
    about_skipped_1: "Zaznaczenie **Zapisz to jako pominiętą dawkę** dopisuje wpis do dziennika i oznacza go jako niewzięty. To zapis, a nie jego brak, i o to właśnie chodzi: aplikacja odróżnia dawkę, z której świadomie zrezygnowałeś, od takiej, której nikt nigdy nie zapisał, a twoje stosowanie raportuje obie osobno zamiast wrzucać je pod pominięte.",
    about_skipped_stops: "Czego to nie robi",
    about_skipped_vial: "Żadna fiolka nie jest uszczuplana. Zmień istniejącą dawkę z wziętej na pominiętą, a masa wraca do fiolki, z której pochodziła. Usuń pominięty wpis, a nic nie wraca, bo nic nie zostało wzięte.",
    about_skipped_curve: "W organizmie nie jest modelowany żaden lek, więc krzywa, procent szczytu i projekcja pozostają nietknięte.",
