    about_skipped_left_out: "Jest pomijana w porównaniach wyników, w rotacji miejsc wstrzyknięć, w znacznikach dawek na wykresie wagi i w protokole, który aplikacja wnioskuje z twojej historii.",
    about_skipped_greyed: "Pola dawki, jednostek i fiolki są wyszarzone, dopóki zaznaczenie jest ustawione, bo dla dawki, która się nie odbyła, żadne z nich nic nie znaczy.",
