    about_built_by: "Zbudowane przez **Aruna**, początkowo po to, by porządnie śledzić własne protokoły, bo każda inna opcja albo chciała konta, albo źle liczyła. Jest za darmo, nie ma czego kupować, i nic o tobie nie jest zbierane.",
