    about_not_body: "To nie porada medyczna, nie recepta i nie zalecenie, by cokolwiek z tego stosować. Większość substancji tutaj nigdzie nie jest zatwierdzonym lekiem, a materiał sprzedawany do celów badawczych nie ma za sobą regulowanej tożsamości, czystości ani jałowości. Aplikacja może sprawdzić twoją arytmetykę. Nie sprawdzi, co jest w twojej fiolce, i nie zastąpi lekarza, który zna twoją historię.",
